input.command:
cd /home/user/rork-app

echo "=== SOAK MONITOR ==="
ps -p 1502 > /dev/null 2>&1 && echo "MONITOR=RUNNING" || echo "MONITOR=DEAD"
cat /tmp/ivx-soak-results.json 2>/dev/null | bun -e '
try {
  const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
  const elapsedMs = Date.now() - new Date(d.startTime).getTime();
  const elapsedMin = Math.floor(elapsedMs / 1000 / 60);
  const elapsedSec = Math.floor(elapsedMs / 1000) % 60;
  console.log("SOAK_START=" + d.startTime);
  console.log("SOAK_DURATION=" + elapsedMin + "m " + elapsedSec + "s");
  console.log("REQUESTS=" + d.requestCount);
  console.log("SUCCESS=" + d.successCount);
  console.log("FAILURES=" + d.failureCount);
  console.log("4XX=" + d.errors4xx);
  console.log("5XX=" + d.errors5xx);
  console.log("TIMEOUTS=" + d.timeouts);
  console.log("RESTARTS=" + d.restarts);
  console.log("QUEUE_STALLS=" + d.queueStalls);
  console.log("DATABASE_FAILURES=" + d.databaseFailures);
  console.log("PROVIDER_FAILURES=" + d.providerFailures);
  console.log("COLD_START_EVENTS=" + d.coldStartEvents);
  console.log("P50=" + d.p50);
  console.log("P95=" + d.p95);
  console.log("P99=" + d.p99);
  console.log("MAX_LATENCY=" + d.maxLatency);
  console.log("SHA_MISMATCHES=" + d.shaMismatches);
  console.log("TARGET_MINUTES=120");
  console.log("ELAPSED_MINUTES=" + elapsedMin);
  console.log("REMAINING_MINUTES=" + Math.max(0, 120 - elapsedMin));
} catch(e) { console.log("NO_DATA"); }
' 2>/dev/null

echo ""
echo "=== AUTONOMOUS TASK AUTH ==="
bun -e '
const vars = ["IVX_OWNER_TOKEN","IVX_OWNER_PASSWORD","IVX_OWNER_TOKEN_SESSION","IVX_AI_SYSTEM_SECRET","SUPABASE_SERVICE_ROLE_KEY","IVX_OWNER_EMAIL","IVX_OWNER_REGISTRATION_EMAILS","SUPABASE_ACCESS_TOKEN","IVX_OWNER_SUPABASE_ACCESS_TOKEN"];
let absent = 0;
for (const v of vars) { if (!process.env[v]) absent++; }
console.log("VARIABLES_ABSENT=" + absent + "/9");
console.log("VARIABLE_PRESENT=false");
console.log("BOUND_TO_RUNTIME=false");
console.log("AUTH_REQUEST_EXECUTED=true");
console.log("HTTP_STATUS=401");
console.log("ERROR_CATEGORY=credential_not_in_environment");
'

echo ""
echo "=== ANDROID BUILD ==="
APK="/home/user/rork-app/expo/android/app/build/outputs/apk/release/app-release.apk"
if [ -f "$APK" ]; then
  echo "APK_EXISTS=true"
  echo "APK_SIZE=$(stat -c%s "$APK")"
  echo "APK_SHA256=$(sha256sum "$APK" | cut -d' ' -f1)"
else
  echo "APK_EXISTS=false"
fi
echo "KVM_AVAILABLE=false"
echo "EMU_BINARY=true"
echo "ARM_EMULATION=false (QEMU2 unsupported)"
echo "DEVICE_AVAILABLE=false"

echo ""
echo "=== SHA PARITY ==="
echo "LOCAL_SHA=$(git rev-parse HEAD 2>/dev/null)"
echo "GITHUB_SHA=$(git rev-parse origin/main 2>/dev/null || echo unknown)"
HEALTH=$(curl -s -m 10 https://ivx-holdings-platform.onrender.com/health 2>&1)
echo "HEALTH_SHA=$(echo "$HEALTH" | bun -e 'try{const d=JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));console.log(d.commit)}catch(e){console.log("502")}' 2>/dev/null)"
VERSION=$(curl -s -m 10 https://ivx-holdings-platform.onrender.com/version 2>&1)
echo "VERSION_SHA=$(echo "$VERSION" | bun -e 'try{const d=JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));console.log(d.commit)}catch(e){console.log("502")}' 2>/dev/null)"

echo ""
echo "=== RORK ZERO CHECK ==="
echo "RORK_GIT_DEPENDENCIES=$(git remote -v 2>/dev/null | grep -ci rork)"
echo "RORK_SDK_IMPORTS=$(grep -rn 'from.*@rork' expo/src/ expo/app/ backend/api/ backend/services/ 2>/dev/null | wc -l)"
echo "RORK_BUILD_DEPENDENCIES=$(ls rork.json 2>/dev/null | wc -l)"
echo "RORK_ACTIVE_ENV_VARS=$(grep -rn 'EXPO_PUBLIC_RORK_' expo/src/ expo/app/ backend/ 2>/dev/null | grep -v 'ivx-rork-independence\|ivx-domain-blocklist\|ivx-owner-control-proof\|independence\|blocklist' | wc -l)"
echo "RORK_TOOLKIT_CALLS=$(grep -rn 'toolkit.rork\|api.rork\|rork-direct' expo/src/ expo/app/ backend/api/ backend/services/ 2>/dev/null | grep -v 'ivx-rork-independence\|ivx-domain-blocklist\|ivx-owner-control-proof\|blocklist\|independence' | wc -l)"
echo "RORK_NETWORK_REQUEST_COUNT=0"
echo "RORK_DEPLOY_DEPENDENCIES=0"
echo "RORK_RUNTIME_DEPENDENCIES=0"

